from ta_messaging import message_types
from ta_messaging.exceptions import ProtocolNotSupported, TranslationOfMessageTypeToAsnNotPossible


def _map_user_protocol_to_database_protocols(user_protocol):
    return str(user_protocol).lower()


def _assert_exists_in_and_get_list(arg_type):
    allowed_values = ['3gpp', 'non-3gpp', 'any']
    assert arg_type in allowed_values, 'Only supported values: {}'.format(allowed_values)
    if arg_type == 'any':
        return ['3gpp', 'non-3gpp']
    else:
        return [arg_type]


def supported_protocols():
    """
    Get all supported protocols
    """
    return message_types.supported_protocols


def protocol_exists(protocol):
    """
    Check in protocol is supproted and contains any messages
    """
    protocol = _map_user_protocol_to_database_protocols(protocol)
    return True if protocol in supported_protocols() and \
                   protocol in list(message_types.message_types.keys()) \
                   and len(message_types.message_types[protocol]) > 0 else False


def message_exists_in_protocol(message_type, protocol, exists_in='3gpp'):
    """
    Check if message type exists in particular protocol
    """
    exists_in_list = _assert_exists_in_and_get_list(exists_in)
    protocol = _map_user_protocol_to_database_protocols(protocol)
    protocols_in_structure = list(message_types.message_types.keys())
    if protocol in supported_protocols() and protocol in protocols_in_structure:
        return _if_message_in_protocol(message_type, protocol, exists_in_list)
    else:
        raise ProtocolNotSupported('Protocol: {} not found in supported protocols: {} or message types: {}'
                                   .format(protocol, supported_protocols(), protocols_in_structure))


def all_messages_in_protocol(protocol, name_from_3gpp=True):
    """
    Get all messages for given protol. if name_form_3goo=False, left side is returned, else right

    """
    protocol = _map_user_protocol_to_database_protocols(protocol)
    if protocol_exists(protocol):
        if name_from_3gpp is True:
            return list(message_types.message_types[protocol].values())
        else:
            return list(message_types.message_types[protocol].keys())
    else:
        protocols_in_structure = list(message_types.message_types.keys())
        raise ProtocolNotSupported('Protocol: {} not found in supported protocols: {} or message types: {}'
                                   .format(protocol, supported_protocols(), protocols_in_structure))


def _if_message_in_protocol(message_type, protocol, exists_in_list):
    protocol = _map_user_protocol_to_database_protocols(protocol)
    ret_val = False
    if '3gpp' in exists_in_list:
        prot_3gpp_msg_names = list(message_types.message_types[protocol].values())
        ret_val = True if message_type in prot_3gpp_msg_names else False
    elif 'non-3gpp' in exists_in_list and ret_val is False:
        prot_names_non_3gpp = list(message_types.message_types[protocol].keys())
        ret_val = True if message_type in prot_names_non_3gpp else False
    return ret_val


def message_exists(message_type, exists_in='3gpp'):
    """
    Check if message exists in any protocol. In case in_3gpp_name_only=True, checks only in names starting with
    capital letter e.g. (left side - visible in message, right side is 3gpp name)
    'sib11': 'SystemInformationBlockType11'

    """
    exists_in_list = _assert_exists_in_and_get_list(exists_in)
    protocols_in_structure = list(message_types.message_types.keys())
    for prot in protocols_in_structure:
        ret = _if_message_in_protocol(message_type, prot, exists_in_list)
        if ret is True:
            return True
    return False


def get_3gpp_name(non_3gpp_name):
    """
    returns translation like rrcConnectionRequest --> RRCConnectionRequest, works only for legacy as rrc and nr-rrc have common
    non-3gpp names and cannot be deterministicly translated
    """
    excluded_protocols = ['nr-rrc']
    protocols_in_structure = list(message_types.message_types.keys())
    for prot in protocols_in_structure:
        if prot in excluded_protocols:
            continue
        prot_names_non_3gpp = list(message_types.message_types[prot].keys())
        if non_3gpp_name in prot_names_non_3gpp:
            return message_types.message_types[prot][non_3gpp_name]
    raise TranslationOfMessageTypeToAsnNotPossible('Non-3gpp message name: {} not found in any messages types'
                                                   .format(non_3gpp_name))
